import osimport jsonimport subprocessimport oracledbENVIRONMENTS = {    "Smoke2": {        "broker_dir": "message-broker2",        "properties": "TradeEntryAPIProperties-BLOOMBERG-BLOXT-Test2.properties"    },    "Smoke3": {        "broker_dir": "message-broker3",        "properties": "TradeEntryAPIProperties-Bloomberg-BLOXT_TEST.properties"    }}def test_cp():    return "Classpath generated automatically."def search_trade(environment, external_reference):    try:        with open("db_config.json", "r") as f:            db_config = json.load(f)        config = db_config[environment]        connection = oracledb.connect(            user=config["username"],            password=config["password"],            host=config["host"],            port=config["port"],            service_name=config["service_name"]        )        cursor = connection.cursor()        cursor.execute(            """            SELECT                TRADE_ID,                EXTERNAL_REFERENCE,                TRADE_DATE_TIME,                ENTERED_DATE,                TRADE_STATUS,                ENTERED_USER,                TRADE_CURRENCY,                QUANTITY            FROM TRADE            WHERE EXTERNAL_REFERENCE = :1            ORDER BY ENTERED_DATE DESC            """,            [external_reference]        )        rows = cursor.fetchall()        results = []        for row in rows:            results.append({                "Trade ID": row[0],                "External Reference": row[1],                "Trade Date": row[2],                "Entered Date": row[3],                "Status": row[4],                "Entered User": row[5],                "Currency": row[6],                "Quantity": row[7]            })        cursor.close()        connection.close()        return {            "status": "SUCCESS",            "count": len(results),            "rows": results        }    except Exception as ex:        return {            "status": "FAILED",            "message": str(ex),            "count": 0,            "rows": []        }def submit_trade(environment, xml_content):    try:        if environment not in ENVIRONMENTS:            return {                "status": "FAILED",                "message": f"{environment} is not supported in this release."            }        broker_dir = os.path.join(            os.getcwd(),            ENVIRONMENTS[environment]["broker_dir"]        )        request_dir = os.path.join(            broker_dir,            "request"        )        os.makedirs(            request_dir,            exist_ok=True        )        xml_file = os.path.join(            request_dir,            "trade.xml"        )        with open(            xml_file,            "w",            encoding="utf-8"        ) as f:            f.write(xml_content)        if os.name == "nt":            cp = "*;resources"        else:            cp = "./*:resources"        command = [            "java",            "--add-opens=java.base/java.nio=ALL-UNNAMED",            "--add-opens=java.base/sun.nio.ch=ALL-UNNAMED",            "-cp",            cp,            "com.genpact.qpid.MessageSender",            ENVIRONMENTS[environment]["properties"],            "requestAddress_BLOXT_BGLPRALBBFITPROD",            "trade.xml",            "30"        ]        result = subprocess.run(            command,            capture_output=True,            text=True,            cwd=broker_dir,            timeout=60        )        output = result.stdout        error = result.stderr        if "TradeSubmissionAck" in output:            return {                "status": "SUCCESS",                "message": "Trade submitted successfully",                "environment": environment,                "response": output            }        return {            "status": "FAILED",            "message": "Trade submission failed",            "environment": environment,            "response": output,            "error": error        }    except subprocess.TimeoutExpired:        return {            "status": "FAILED",            "message": "Java process timed out after 60 seconds",            "environment": environment        }    except Exception as ex:        return {            "status": "FAILED",            "message": str(ex),            "environment": environment        }